static inline float quad_elu(float x) { return x > 0.0f ? x : expm1f(x); }

// obs: QUAD_OBS_DIM raw (un-normalised) values; act: QUAD_ACT_DIM out.
static inline void quad_policy_forward(const float *obs, float *act) {
  float a[105], b[105];
  for (int i = 0; i < 105; ++i) a[i] = (obs[i] - QUAD_OBS_MEAN[i]) / QUAD_OBS_STD[i];
  for (int o = 0; o < 96; ++o) {
    float s = QUAD_B0[o];
    const float *w = &QUAD_W0[o * 105];
    for (int i = 0; i < 105; ++i) s += w[i] * a[i];
    b[o] = quad_elu(s);
  }
  for (int o = 0; o < 96; ++o) a[o] = b[o];
  for (int o = 0; o < 64; ++o) {
    float s = QUAD_B1[o];
    const float *w = &QUAD_W1[o * 96];
    for (int i = 0; i < 96; ++i) s += w[i] * a[i];
    b[o] = quad_elu(s);
  }
  for (int o = 0; o < 64; ++o) a[o] = b[o];
  for (int o = 0; o < 8; ++o) {
    float s = QUAD_B2[o];
    const float *w = &QUAD_W2[o * 64];
    for (int i = 0; i < 64; ++i) s += w[i] * a[i];
    b[o] = s;
  }
  for (int o = 0; o < 8; ++o) act[o] = b[o];
}
